        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.adoptionHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            // Engagement is a -40..+40 delta — offset by +50 so it shares the 0–100 axis.
            const engagementShifted = ds.engagementHistory.map((v) => Math.round(v + 50));
            return {
                changeChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.adoptionHistory.map((v) => Math.round(v)) },
                        { data: ds.resistanceHistory },
                        { data: engagementShifted }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.1.0 - verbatim v1.0.0 composite formula (weights 0.42/0.24/0.16/0.18 sum to 1).
            const adoption = Math.round(ds.adoption);
            const resistance = Math.round(ds.resistance);
            const engagement = Math.round(ds.engagement);
            const embed = Math.round(ds.embed * 10) / 10;
            const resistScore = 100 - resistance;
            const engageScore = Math.max(0, Math.min(100, (engagement + 20) * 2.5));
            const embedScore = Math.max(0, Math.min(100, (8 - embed) / 4 * 100));
            return Math.round(adoption * 0.42 + resistScore * 0.24 + engageScore * 0.16 + embedScore * 0.18);
        }

        _gates(ds) {
            const adoption = Math.round(ds.adoption);
            return {
                onTarget: adoption >= this.TARGET_ADOPTION,
                aboveCancel: adoption >= this.CANCEL_ADOPTION,
                resistanceFell: Math.round(ds.resistance) <= 35,
                embedded: (Math.round(ds.embed * 10) / 10) <= this.EMBED_TARGET
            };
        }

        _finalScore(ds) {
            // v1.2.0 - month-9 score: a run cannot sit in a band whose label is untrue of it.
            // Below the cancel line the renewal band is out of reach; with a month-9 target
            // missed the top band is out of reach.
            let s = this._composite(ds);
            const g = this._gates(ds);
            if (!g.aboveCancel) s = Math.min(s, this.BAND_RENEWAL - 1);
            else if (!(g.onTarget && g.resistanceFell && g.embedded)) s = Math.min(s, this.BAND_EMBEDDED - 1);
            return s;
        }

        formatCompletionMessage(summary) {
            // v1.1.0 FIX B - localized board-debrief scorecard (was: framework default that discarded
            // score, tier, targets and insights).
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? window.mySimulation.t.bind(window.mySimulation)
                : function (k) { return k; };
            summary = summary || {};
            const score = (summary.composite != null) ? summary.composite : (summary.score != null ? summary.score : 0);
            const verdict = summary.gradeKey ? t(summary.gradeKey) : (summary.performanceLabel || '');
            const insights = summary.insights || [];
            const chip = function (ok, label) {
                return '<div class="cc-cm-target ' + (ok ? 'cc-cm-met' : 'cc-cm-missed') + '">'
                    + '<span class="cc-cm-tick">' + (ok ? '✓' : '✗') + '</span><span>' + label + '</span></div>';
            };
            const targets = ''
                + chip(!!summary.onTarget, t('tgt_adoption'))
                + chip(!!summary.aboveCancel, t('tgt_cancel'))
                + chip(!!summary.resistanceFell, t('tgt_resistance'))
                + chip(!!summary.embedded, t('tgt_embed'));
            const metric = function (label, val) {
                return '<div class="cc-cm-metric"><span>' + label + '</span><strong>' + val + '</strong></div>';
            };
            const eng = summary.engagement;
            const engStr = (eng != null) ? ((eng > 0 ? '+' : '') + eng) : '-';
            const embStr = (summary.embed != null) ? this._fmtMonths(Number(summary.embed)) : '-';
            const metrics = ''
                + metric(t('kpi_adoption'), (summary.adoption != null ? summary.adoption : '-') + '%')
                + metric(t('kpi_resistance'), (summary.resistance != null ? summary.resistance : '-') + '/100')
                + metric(t('kpi_engagement'), engStr)
                + metric(t('kpi_budget'), '€' + (summary.budget != null ? summary.budget : '-') + 'K')
                + metric(t('kpi_embed'), embStr + ' ' + t('unit_mo'));
            const items = insights.map(function (s) { return '<li>' + s + '</li>'; }).join('');
            const subs = '<div class="cc-cm-subscores">'
                + '<span>' + t('comp_sub_outcome') + ': <strong>' + (summary.targetsMet != null ? summary.targetsMet : 0) + ' ' + t('comp_of') + ' 4</strong></span>'
                + '<span>' + t('comp_sub_process') + ': <strong>' + (summary.errorsAvoided != null ? summary.errorsAvoided : 0) + ' ' + t('comp_of') + ' 5</strong></span>'
                + '</div>';
            const tp = summary.turningPoint
                ? '<div class="cc-cm-tp"><strong>' + t('tp_heading') + '</strong> ' + summary.turningPoint + '</div>' : '';
            const qs = (summary.questions || []).map(function (s) { return '<li>' + s + '</li>'; }).join('');
            return ''
                + '<div class="cc-cm">'
                +   '<div class="cc-cm-heading">' + t('comp_heading') + '</div>'
                +   '<div class="cc-cm-verdict">' + verdict + '</div>'
                +   '<div class="cc-cm-score">' + t('comp_score_label') + ': <strong>' + score + '</strong> / 100</div>'
                +   subs
                +   '<div class="cc-cm-sub">' + t('comp_targets_heading') + '</div>'
                +   '<div class="cc-cm-targets">' + targets + '</div>'
                +   '<div class="cc-cm-metrics">' + metrics + '</div>'
                +   tp
                +   (items ? '<ul class="cc-cm-insights">' + items + '</ul>' : '')
                +   (qs ? '<div class="cc-cm-sub">' + t('q_heading') + '</div><ol class="cc-cm-questions">' + qs + '</ol>' : '')
                + '</div>';
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const t = (window.mySimulation && typeof window.mySimulation.t === 'function') ? window.mySimulation.t.bind(window.mySimulation) : function (k) { return k; };
            const ds = window.mySimulation.state.domainState;
            const adoption = Math.round(ds.adoption);
            const resistance = Math.round(ds.resistance);
            const engagement = Math.round(ds.engagement);
            const budget = Math.round(ds.budget);
            const embed = Math.round(ds.embed * 10) / 10;

            // v1.2.0 - one function derives the band, the label and the insights from the score.
            const complete = history.length >= this.ROUNDS.length;
            const composite = complete ? this._finalScore(ds) : this._composite(ds);
            const g = this._gates(ds);
            const onTarget = g.onTarget, aboveCancel = g.aboveCancel, resistanceFell = g.resistanceFell, embedded = g.embedded;
            const targetsMet = (onTarget ? 1 : 0) + (aboveCancel ? 1 : 0) + (resistanceFell ? 1 : 0) + (embedded ? 1 : 0);

            let band = 'notjustified', perfKey = 'grade_lost';
            if (composite >= this.BAND_EMBEDDED) { band = 'embedded'; perfKey = 'grade_embedded'; }
            else if (composite >= this.BAND_RENEWAL) { band = 'renewal'; perfKey = 'grade_renewal'; }

            // The five common errors, each read from what was decided in this run.
            const er = ds.errorRound || {};
            const errors = [];
            if (er.broadcast) errors.push({ k: 'broadcast', r: er.broadcast });
            if (er.frontline && !ds.managersEnabled) errors.push({ k: 'frontline', r: er.frontline });
            if (er.momentum) errors.push({ k: 'momentum', r: er.momentum });
            if (er.capacity) errors.push({ k: 'capacity', r: er.capacity });
            if (er.launch) errors.push({ k: 'launch', r: er.launch });
            errors.sort(function (x, y) { return x.r - y.r; });
            const errorsAvoided = 5 - errors.length;
            let pattern = errors.length ? errors[0].k : (band === 'embedded' ? 'embedded' : 'mixed');

            let turningPoint = t('tp_none');
            if (errors.length) {
                turningPoint = t('tp_round') + ' ' + errors[0].r + ' — ' + t('err_' + errors[0].k) + '. ' + t('tp_' + errors[0].k);
            }

            const insights = [];
            if (band === 'embedded') insights.push(t('insight_embedded'));
            else if (!aboveCancel) insights.push(t('insight_cancelled'));
            else if (band === 'renewal') insights.push(t('insight_mixed'));
            else insights.push(t('insight_low'));
            const insightKey = { broadcast: 'insight_broadcast', frontline: 'insight_nomultiplier', momentum: 'insight_momentum', capacity: 'insight_capacity', launch: 'insight_decay' };
            for (let i = 0; i < errors.length && insights.length < 4; i++) insights.push(t(insightKey[errors[i].k]));
            if (insights.length < 5 && ds.overspent) insights.push(t('insight_overspent'));
            if (insights.length < 5 && resistance >= 55) insights.push(t('insight_resistance_high'));
            if (insights.length < 5 && !embedded && onTarget) insights.push(t('insight_slow_embed'));
            if (insights.length < 5 && ds.managersEnabled && onTarget) insights.push(t('insight_multiplier_used'));

            return {
                gradeKey: perfKey,
                performanceKey: perfKey,
                performance: band,
                performanceLabel: t(perfKey),
                score: composite,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                adoption: adoption,
                resistance: resistance,
                engagement: engagement,
                budget: budget,
                embed: embed,
                onTarget: onTarget,
                aboveCancel: aboveCancel,
                resistanceFell: resistanceFell,
                embedded: embedded,
                targetsMet: targetsMet,
                errorsAvoided: errorsAvoided,
                pattern: pattern,
                turningPoint: turningPoint,
                insights: insights,
                questions: [t('q_1'), t('q_2'), t('q_3')]
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.adoption < this.CANCEL_ADOPTION && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cancel`);
            if (ds.frontlineFirst && !ds.managersEnabled) return window.mySimulation.t(`hint_managers`);
            if (ds.broadcastBias && ds.resistance >= 50) return window.mySimulation.t(`hint_broadcast`);
            if (ds.uniformHeavy && ds.budget <= 120) return window.mySimulation.t(`hint_budget`);
            if (ds.momentumOverRescue) return window.mySimulation.t(`hint_rescue`);
            if (ds.launchAsSuccess) return window.mySimulation.t(`hint_reinforce`);
            if (ds.adoption >= this.TARGET_ADOPTION && ds.resistance <= 35) return window.mySimulation.t(`hint_strong`);
            return null;
        }

